	function getModel(modelId) {
		const model = MODELS[modelId];
		if (!model) throw new Error(`Unknown model ${modelId}`);
		return model;
	}
	function paramSpec(model, key) {
		const spec = model.params.find((p) => p.key === key);
		if (!spec) throw new Error(`Model ${model.id} has no parameter ${key}`);
		return spec;
	}
	function evaluate(modelId, version, params) {
		const model = getModel(modelId);
		const fn = model.versions[version];
		if (!fn) throw new Error(`Model ${modelId} has no version ${version}`);
		return fn(Object.fromEntries(model.params.map((p) => [p.key, params[p.key] ?? p.default])));
	}
	function linspace(lo, hi, n) {
		if (n < 2) return [lo];
		return Array.from({ length: n }, (_, i) => lo + (hi - lo) * i / (n - 1));
	}
	function sweep(modelId, version, base, xKey, yKey, steps = 12) {
		const model = getModel(modelId);
		const px = paramSpec(model, xKey);
		const py = paramSpec(model, yKey);
		const xs = linspace(px.min, px.max, steps);
		const ys = linspace(py.min, py.max, steps);
		const grid = ys.map((y) => xs.map((x) => evaluate(modelId, version, {
			...base,
			[xKey]: x,
			[yKey]: y
		})));
		const flat = grid.flat();
		return {
			xs,
			ys,
			grid,
			min: Math.min(...flat),
			max: Math.max(...flat)
		};
	}
	function sensitivity(modelId, version, base) {
		return getModel(modelId).params.map((p) => {
			const step = .1 * (p.max - p.min);
			const at = base[p.key] ?? p.default;
			const lo = evaluate(modelId, version, {
				...base,
				[p.key]: Math.max(p.min, at - step)
			});
			const hi = evaluate(modelId, version, {
				...base,
				[p.key]: Math.min(p.max, at + step)
			});
			return {
				key: p.key,
				label: p.label,
				delta: hi - lo
			};
		}).sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));
	}
	function makeRun({ modelId, version, params, author, note = "", parent = null, date = (/* @__PURE__ */ new Date()).toISOString() }) {
		const value = evaluate(modelId, version, params);
		return {
			id: `run-${Date.now().toString(36)}${Math.floor(Math.random() * 1e4).toString(36)}`,
			modelId,
			version,
			params: { ...params },
			value,
			author,
			note,
			parent,
			date
		};
	}
	function runDiff(run, parent) {
		if (!parent) return [];
		const changes = Object.keys(run.params).filter((k) => run.params[k] !== parent.params[k]).map((k) => ({
			key: k,
			from: parent.params[k],
			to: run.params[k]
		}));
		if (run.version !== parent.version) changes.push({
			key: "model version",
			from: parent.version,
			to: run.version
		});
		return changes;
	}
	function auditRecord(runs, modelId) {
		const model = getModel(modelId);
		return {
			exportedAt: (/* @__PURE__ */ new Date()).toISOString(),
			model: {
				id: model.id,
				name: model.name,
				versions: Object.keys(model.versions)
			},
			runs: runs.filter((r) => r.modelId === modelId).map((r) => ({
				...r,
				output: {
					[model.output.key]: r.value,
					unit: model.output.unit
				}
			}))
		};
	}
